using System;
using System.Collections.Generic;
using RoadRush.Candidates.Articulated;
using RoadRush.Candidates.Compatibility;
namespace RoadRush.Candidates.VisualCoupling {
public sealed class Rod {public string status{get;}public Vec3 start{get;}public Vec3 end{get;}public double length{get;}public Rod(string status,Vec3 start,Vec3 end,double length){this.status=status;this.start=start;this.end=end;this.length=length;}}
public sealed class Link {public string status{get;}public Vec3 start{get;}public Vec3 end{get;}public double length{get;}public double yawDegrees{get;}public double pitchDeltaDegrees{get;}public FrozenList<FrozenList<Vec3>> rings{get;}public Rod rod{get;}public string physics{get;}public Link(string status,Vec3 start,Vec3 end,double length,double yawDegrees,double pitchDeltaDegrees,FrozenList<FrozenList<Vec3>> rings,Rod rod,string physics="NONE_DECORATIVE_ONLY"){this.status=status;this.start=start;this.end=end;this.length=length;this.yawDegrees=yawDegrees;this.pitchDeltaDegrees=pitchDeltaDegrees;this.rings=rings??throw new ArgumentNullException(nameof(rings));this.rod=rod;this.physics=physics;}}
public sealed class LightAnchor {public string id{get;}public int car{get;}public Vec3 position{get;}public Vec3 direction{get;}public string colour{get;}public bool enabled{get;}public string kind{get;}public LightAnchor(string id,int car,Vec3 position,Vec3 direction,string colour,bool enabled=false,string kind="future-anchor-no-emitter"){this.id=id;this.car=car;this.position=position;this.direction=direction;this.colour=colour;this.enabled=enabled;this.kind=kind;}}
public sealed class WheelSpin {public int car{get;}public int bogie{get;}public int axle{get;}public int side{get;}public Vec3 centre{get;}public Vec3 axis{get;}public double radius{get;}public double phaseRadians{get;}public double wrappedPhaseRadians{get;}public string source{get;}public WheelSpin(int car,int bogie,int axle,int side,Vec3 centre,Vec3 axis,double radius,double phaseRadians,double wrappedPhaseRadians,string source="synthetic-host-distance-not-measured-wheel-slip"){this.car=car;this.bogie=bogie;this.axle=axle;this.side=side;this.centre=centre;this.axis=axis;this.radius=radius;this.phaseRadians=phaseRadians;this.wrappedPhaseRadians=wrappedPhaseRadians;this.source=source;}}
public sealed class VisualPackage {public string status{get;}public FrozenList<Link> links{get;}public FrozenList<LightAnchor> lights{get;}public FrozenList<WheelSpin> wheelSpin{get;}public VisualPackage(string status,FrozenList<Link> links,FrozenList<LightAnchor> lights,FrozenList<WheelSpin> wheelSpin){this.status=status;this.links=links??throw new ArgumentNullException(nameof(links));this.lights=lights??throw new ArgumentNullException(nameof(lights));this.wheelSpin=wheelSpin??throw new ArgumentNullException(nameof(wheelSpin));}}
public static class Decorative {
 static double Angle(Vec3 a,Vec3 b){a=Vec.Unit(a);b=Vec.Unit(b);return Math.Acos(Math.Clamp(Vec.Dot(a,b),-1,1))*180/Math.PI;}
 static bool Finite(Vec3 v)=>double.IsFinite(v.X)&&double.IsFinite(v.Y)&&double.IsFinite(v.Z);
 static void Valid(Frame f){if(!Finite(f.origin)||!Finite(f.right)||!Finite(f.up)||!Finite(f.forward))throw new ArgumentException("invalid frame");if(Math.Abs(Vec.Norm(f.right)-1)>1e-8||Math.Abs(Vec.Norm(f.up)-1)>1e-8||Math.Abs(Vec.Norm(f.forward)-1)>1e-8)throw new ArgumentException("nonunit frame");if(Math.Abs(Vec.Dot(f.right,f.up))>1e-8||Math.Abs(Vec.Dot(f.right,f.forward))>1e-8||Math.Abs(Vec.Dot(f.up,f.forward))>1e-8)throw new ArgumentException("nonorthogonal frame");}
 public static Link Between(Car a,Car b){Valid(a.body);Valid(b.body);var af=a.body;var bf=b.body;var start=af.Local(new Vec3(0,2,-11.5));var end=bf.Local(new Vec3(0,2,11.5));var length=Vec.Norm(Vec.Sub(end,start));var yaw=Angle(new Vec3(af.forward[0],0,af.forward[2]),new Vec3(bf.forward[0],0,bf.forward[2]));var pitch=Math.Abs((Math.Asin(af.forward[1])-Math.Asin(bf.forward[1]))*180/Math.PI);var rodA=a.couplers[0];var rodB=b.couplers[1];var rodLength=Vec.Norm(Vec.Sub(rodB,rodA));var visible=length>=.5&&length<=1.6&&yaw<=15&&pitch<=8;var rodVisible=rodLength>=.35&&rodLength<=1&&yaw<=15&&pitch<=8;var rings=new FrozenList<Vec3>[visible?7:0];if(visible)for(int i=0;i<7;i++){double f=i/6d;var origin=Vec.Add(start,Vec.Mul(Vec.Sub(end,start),f));var right=Vec.Unit(Vec.Add(Vec.Mul(af.right,1-f),Vec.Mul(bf.right,f)));var up0=Vec.Add(Vec.Mul(af.up,1-f),Vec.Mul(bf.up,f));var up=Vec.Unit(Vec.Sub(up0,Vec.Mul(right,Vec.Dot(up0,right))));double rib=i%2==1?.025:0;var ring=new Vec3[4];for(int j=0;j<4;j++){int x=j<2?-1:1,y=j==0||j==3?-1:1;ring[j]=Vec.Add(origin,Vec.Add(Vec.Mul(right,x*(.5+rib)),Vec.Mul(up,y*(.7+rib))));}rings[i]=FrozenList<Vec3>.Own(ring);}return new Link(visible?"visible":"hidden-limit",start,end,length,yaw,pitch,FrozenList<FrozenList<Vec3>>.Own(rings),new Rod(rodVisible?"visible":"hidden-limit",rodA,rodB,rodLength));}
 public static VisualPackage Build(Pose pose){if(pose.status!="active")return new VisualPackage("inactive-pose",FrozenList<Link>.Own(Array.Empty<Link>()),FrozenList<LightAnchor>.Own(Array.Empty<LightAnchor>()),FrozenList<WheelSpin>.Own(Array.Empty<WheelSpin>()));var cars=pose.cars;if(cars.Length<2)throw new ArgumentException("consist");var links=new Link[cars.Length-1];for(int i=1;i<cars.Length;i++)links[i-1]=Between(cars[i-1],cars[i]);var lights=new LightAnchor[4];for(int end=0;end<2;end++)for(int side=0;side<2;side++){var index=end==0?0:cars.Length-1;var frame=cars[index].body;var role=end==0?"front":"rear";lights[end*2+side]=new LightAnchor(role+"-"+(side==0?"left":"right"),index,frame.Local(new Vec3(side==0?-.78:.78,1.65,end==0?11.56:-11.56)),Vec.Mul(frame.forward,end==0?1:-1),end==0?"white":"red");}var wheels=new WheelSpin[cars.Length*8];int wi=0;for(int c=0;c<cars.Length;c++)for(int b=0;b<cars[c].bogies.Length;b++)for(int a=0;a<cars[c].bogies[b].axles.Length;a++)for(int w=0;w<cars[c].bogies[b].axles[a].wheels.Length;w++){var axle=cars[c].bogies[b].axles[a];var wheel=axle.wheels[w];double mod=wheel.phase%(2*Math.PI);if(mod<0)mod+=2*Math.PI;wheels[wi++]=new WheelSpin(c,b,a,w,wheel.centre,axle.frame.right,.42,wheel.phase,mod);}return new VisualPackage("active-visual-only",FrozenList<Link>.Own(links),FrozenList<LightAnchor>.Own(lights),FrozenList<WheelSpin>.Own(wheels));}
}
}
